pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with too much unused space
    if post_residual > 50.0 {
        score -= (post_residual - 50.0).powi(2);
    }

    // Reward fitting items into existing bins
    if fitting_bins_count > 0 {
        score += 0.1 * fitting_bins_count as f64;
    }

    // Penalize opening new bins
    score -= open_bins_count as f64;

    // Reward maintaining low mean residual across all bins
    score += 0.5 * (mean_residual / bin_capacity);

    // Lookahead reward for future fitability
    if next_item_size > 0 {
        let lookahead_penalty = if post_residual < next_item_size { 100.0 } else { 0.0 };
        score -= lookahead_penalty;
    }

    // Penalize items that don't fit in the current bin
    if item_size > bin_residual {
        score -= 200.0;
    }

    score
}

