pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Lookahead penalty for the next item
    if next_item_size > 0 {
        let lookahead_penalty = if post_residual < next_item_size { 120.0 } else { 0.0 };
        score -= lookahead_penalty;
    }

    // Penalize bins that are too close to being full or empty
    if (bin_capacity - bin_residual) > 85 || (bin_capacity - bin_residual) < 15 {
        score += 0.7;
    }

    // Penalize bins with zero residual space
    if post_residual == 0 {
        score -= 0.35;
    }

    // Reward bins with small residual space
    if post_residual < 25 {
        score += 0.3 * (25 - post_residual) as f64 / 25.0;
    }

    // Penalize if there are open bins
    if open_bins_count > 0 {
        score -= 0.1 * (open_bins_count as f64 / total_items as f64);
    }

    // Reward bins that fit multiple items
    if fitting_bins_count > 0 {
        score += 0.35;
    }

    // Penalize small next item sizes
    if next_item_size > 0 && next_item_size < 20 {
        score -= 0.1 * (20 - next_item_size) as f64 / 20.0;
    }

    // Reward bins with high residual space
    if post_residual > 75 {
        score += 0.1 * (post_residual - 75) as f64 / 15.0;
    }

    // Penalize mean residual to encourage better bin utilization
    score -= mean_residual / 25.0;

    score
}
